svg.script:
window.onload = function () {
  const NS = "http://www.w3.org/2000/svg";
  const svg = document.documentElement;

  // Horizontal values: d × k / capacity
  const capacities = [
    4, 16, 64, 256, 1024, 4096, 8192, 16384
  ];

  // Vertical values: number of demes
  const demes = [
    2, 4, 8, 16, 25, 35, 50,
    70, 100, 150, 250, 350, 500
  ];

  const values = [
    [0.71, 0.45, 0.44, 0.52, 0.51, 1.07, 1.99, 6.63],
    [0.56, 0.45, 0.48, 0.37, 0.47, 0.69, 1.59, 6.31],
    [0.42, 0.36, 0.33, 0.32, 0.41, 0.65, 1.69, 13.15],
    [0.36, 0.51, 0.43, 0.30, 0.49, 0.56, 1.03, 12.97],
    [0.96, 0.35, 0.30, 0.56, 0.47, 0.54, 1.18, 13.00],
    [0.45, 0.36, 0.43, 0.28, 0.23, 0.86, 1.84, 6.78],
    [0.38, 0.22, 0.46, 0.21, 0.37, 0.36, 1.32, 4.40],
    [0.45, 0.53, 0.26, 0.20, 0.32, 0.21, 1.39, 4.39],
    [0.80, 0.43, 0.17, 0.15, 0.17, 0.17, 0.68, 2.76],
    [0.87, 0.22, 0.27, 0.08, 0.11, 0.27, 0.56, 1.97],
    [0.40, 0.43, 0.16, 0.15, 0.12, 0.23, 0.35, 1.14],
    [0.43, 0.35, 0.19, 0.13, 0.09, 0.19, 0.32, 0.88],
    [0.39, 0.35, 0.23, 0.14, 0.14, 0.15, 0.24, 0.67]
  ];

  const plot = {
    left: 150,
    top: 90,
    width: 780,
    height: 590
  };

  // Logarithmic axis domains.
  const xMin = 2;
  const xMax = 32768;
  const yMin = 1;
  const yMax = 800;

  function el(name, attrs, parent = svg) {
    const element = document.createElementNS(NS, name);

    for (const [key, value] of Object.entries(attrs || {})) {
      element.setAttribute(key, value);
    }

    parent.appendChild(element);
    return element;
  }

  function text(
    content,
    x,
    y,
    className,
    anchor = "middle"
  ) {
    const element = el("text", {
      x: x,
      y: y,
      class: className,
      "text-anchor": anchor
    });

    element.textContent = content;
    return element;
  }

  function logX(value) {
    return plot.left +
      (
        (Math.log10(value) - Math.log10(xMin)) /
        (Math.log10(xMax) - Math.log10(xMin))
      ) * plot.width;
  }

  function logY(value) {
    return plot.top + plot.height -
      (
        (Math.log10(value) - Math.log10(yMin)) /
        (Math.log10(yMax) - Math.log10(yMin))
      ) * plot.height;
  }

  function interpolateColor(c1, c2, t) {
    t = Math.max(0, Math.min(1, t));

    const rgb1 = c1.match(/\w\w/g).map(v => parseInt(v, 16));
    const rgb2 = c2.match(/\w\w/g).map(v => parseInt(v, 16));

    const rgb = rgb1.map((v, i) =>
      Math.round(v + (rgb2[i] - v) * t)
    );

    return "#" + rgb
      .map(v => v.toString(16).padStart(2, "0"))
      .join("");
  }

  /*
   * Color scale:
   *
   * Values below 1:
   *   red/orange -> white
   *
   * Value 1:
   *   neutral white
   *
   * Values above 1:
   *   white -> blue
   *
   * The interpolation is logarithmic so that values such as
   * 0.1, 1, and 10 are visually comparable.
   */
  function colorFor(value) {
    const neutral = 1;

    if (value <= neutral) {
      const t =
        (Math.log10(value) - Math.log10(0.05)) /
        (Math.log10(neutral) - Math.log10(0.05));

      return interpolateColor("#d73027", "#ffffff", t);
    }

    const t =
      (Math.log10(value) - Math.log10(neutral)) /
      (Math.log10(16) - Math.log10(neutral));

    return interpolateColor("#ffffff", "#4575b4", t);
  }

  function textColor(value) {
    if (value < 0.25 || value > 3.5) {
      return "#ffffff";
    }

    return "#222222";
  }

  // Plot border
  el("rect", {
    x: plot.left,
    y: plot.top,
    width: plot.width,
    height: plot.height,
    fill: "#ffffff",
    class: "axis"
  });

  // Logarithmic x-axis ticks
  const xTicks = [
    2, 4, 16, 64, 256,
    1024, 4096, 8192, 16384, 32768
  ];

  xTicks.forEach(value => {
    const x = logX(value);

    el("line", {
      x1: x,
      y1: plot.top,
      x2: x,
      y2: plot.top + plot.height,
      class: "grid"
    });

    text(
      value.toLocaleString(),
      x,
      plot.top + plot.height + 24,
      "tick-label"
    );
  });

  // Logarithmic y-axis ticks
  const yTicks = [
    1, 2, 4, 8, 16, 32,
    64, 128, 256, 512
  ];

  yTicks.forEach(value => {
    const y = logY(value);

    el("line", {
      x1: plot.left,
      y1: y,
      x2: plot.left + plot.width,
      y2: y,
      class: "grid"
    });

    text(
      String(value),
      plot.left - 12,
      y + 4,
      "tick-label",
      "end"
    );
  });

  /*
   * Cell boundaries:
   *
   * Horizontal boundaries are geometric midpoints between
   * neighboring logarithmic data coordinates.
   */
  const xBoundaries = [
    2, 8, 32, 128, 512,
    2048, 5792.62, 11585.24, 32768
  ];

  const yBoundaries = [1];

  for (let i = 0; i < demes.length - 1; i++) {
    yBoundaries.push(Math.sqrt(demes[i] * demes[i + 1]));
  }

  yBoundaries.push(800);

  // Draw heat-map cells
  for (let row = 0; row < demes.length; row++) {
    for (let col = 0; col < capacities.length; col++) {
      const x1 = logX(xBoundaries[col]);
      const x2 = logX(xBoundaries[col + 1]);

      // SVG y-coordinates increase downward.
      const yTop = logY(yBoundaries[row + 1]);
      const yBottom = logY(yBoundaries[row]);

      const value = values[row][col];

      el("rect", {
        x: x1,
        y: yTop,
        width: x2 - x1,
        height: yBottom - yTop,
        fill: colorFor(value),
        class: "cell"
      });

      const label = text(
        value.toFixed(2),
        (x1 + x2) / 2,
        (yTop + yBottom) / 2,
        "cell-label"
      );

      label.setAttribute("fill", textColor(value));
    }
  }

  // Axes
  el("line", {
    x1: plot.left,
    y1: plot.top + plot.height,
    x2: plot.left + plot.width,
    y2: plot.top + plot.height,
    class: "axis"
  });

  el("line", {
    x1: plot.left,
    y1: plot.top,
    x2: plot.left,
    y2: plot.top + plot.height,
    class: "axis"
  });

  // Title
  text(
    "Heat Map of Gjit/V Wall-Clock Ratio",
    plot.left + plot.width / 2,
    42,
    "title"
  );

  // Axis labels
  text(
    "Capacity (log⏨ 4**k)",
    plot.left + plot.width / 2,
    plot.top + plot.height + 58,
    "axis-label"
  );

  const yLabel = text(
    "Demes (log⏨ d)",
    plot.left - 100,
    plot.top + plot.height / 2,
    "axis-label"
  );

  yLabel.setAttribute(
    "transform",
    `rotate(-90 ${plot.left - 100} ${plot.top + plot.height / 2})`
  );

  // Color-scale legend
  const legendX = 150;
  const legendY = 790;
  const legendWidth = 780;
  const legendHeight = 20;

  text(
    "Hot",
    legendX - 12,
    legendY + 15,
    "legend-label",
    "end"
  );

  el("rect", {
    x: legendX,
    y: legendY,
    width: legendWidth,
    height: legendHeight,
    fill: "url(#heatScale)",
    stroke: "#777",
    "stroke-width": 1
  });

  text(
    "Cold",
    legendX + legendWidth + 12,
    legendY + 15,
    "legend-label",
    "start"
  );

  // Legend positions use a logarithmic value scale.
  const legendMin = Math.log10(0.05);
  const legendMax = Math.log10(16);

  const legendTicks = [0.05, 0.1, 0.25, 0.5, 1, 2, 4, 8, 16];

  legendTicks.forEach(value => {
    const position =
      (Math.log10(value) - legendMin) /
      (legendMax - legendMin);

    const x = legendX + position * legendWidth;

    el("line", {
      x1: x,
      y1: legendY + legendHeight,
      x2: x,
      y2: legendY + legendHeight + 6,
      stroke: "#555",
      "stroke-width": 1
    });

    text(
      String(value),
      x,
      legendY + legendHeight + 22,
      "legend-label"
    );
  });

  text(
    "1 = neutral",
    legendX +
      (
        (Math.log10(1) - legendMin) /
        (legendMax - legendMin)
      ) * legendWidth,
    legendY + legendHeight + 44,
    "legend-label"
  );

  text(
    "Both axes use logarithmic scales; lower values are hot and higher values are cold.",
    560,
    875,
    "note"
  );
};
